package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMemberLoansUseCase;
import com.example.lending.application.port.out.CountMemberLoansPort;
import com.example.lending.application.port.out.LoadActiveLoansPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMemberLoansService implements GetMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadActiveLoansPort loadActiveLoansPort;
    private final CountMemberLoansPort countMemberLoansPort;

    public GetMemberLoansService(LoadMemberPort loadMemberPort, LoadActiveLoansPort loadActiveLoansPort,
                                 CountMemberLoansPort countMemberLoansPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadActiveLoansPort = loadActiveLoansPort;
        this.countMemberLoansPort = countMemberLoansPort;
    }

    @Override
    public MemberLoanPage getActiveLoans(GetMemberLoansQuery query) {
        loadMemberPort.loadMember(query.memberId()).orElseThrow(() -> new MemberNotFoundException(query.memberId()));
        List<MemberLoanItem> items = loadActiveLoansPort.loadActiveLoans(query.memberId(), query.page(), query.size())
                .stream()
                .map(l -> new MemberLoanItem(l.loanId(), l.bookId(), l.title(), l.loanedAt(), l.dueAt()))
                .toList();
        return new MemberLoanPage(items, query.page(), query.size(), countMemberLoansPort.countLoans(query.memberId()));
    }
}
