            if (page < 0) {
                throw new IllegalArgumentException("page must be 0 or greater");
            }
            if (size < 1 || size > MAX_PAGE_SIZE) {
                throw new IllegalArgumentException("size must be between 1 and " + MAX_PAGE_SIZE);
            }
        }
    }

    record MemberLoanPage(List<MemberLoanItem> items, int page, int size, int totalCount) {
    }

    record MemberLoanItem(UUID loanId, UUID bookId, String title, LocalDate loanedAt, LocalDate dueAt) {
    }
